<script setup>
import { computed, onMounted, ref } from 'vue'
import { ArrowLeft, ExternalLink, Eye, GripVertical, Info, LoaderCircle, Mail, MessageSquare, Pencil, Plus, Save, Search, ShieldCheck, Star, Target, Trash2 } from 'lucide-vue-next'
import { getReferralLead, getReferralLeads, getReferralProcedures, getReferralProgram, updateReferralLeadStatus, updateReferralProgram } from '@/api/referrals'
import { uploadImage } from '@/api/uploads'
import AppTableList from '@/components/global/AppTableList.vue'
import PublicFormRenderer from '@/components/public-forms/PublicFormRenderer.vue'
import PublicFormView from '@/views/public/PublicFormView.vue'
import { useAuthStore } from '@/stores/auth'

const section = ref('referrals'), view = ref('edit'), loading = ref(true), saving = ref(false)
const authStore = useAuthStore()
const program = ref(null), procedures = ref([]), search = ref(''), message = ref(''), values = ref({})
const leads = ref([]), referralMetrics = ref({}), leadsLoading = ref(true), leadSearch = ref(''), leadStatus = ref('')
const selectedLead = ref(null)
const statuses = [{ value: '', label: 'Todos os status' }, { value: 'new', label: 'Novo' }, { value: 'contacted', label: 'Em contato' }, { value: 'interested', label: 'Interessado' }, { value: 'scheduled', label: 'Agendado' }, { value: 'converted', label: 'Convertido' }, { value: 'lost', label: 'Perdido' }]
const fields = [
  { key: 'email', label: 'E-mail', icon: Mail },
  { key: 'objective', label: 'Objetivo principal', icon: Target },
  { key: 'serviceInterest', label: 'Serviço de interesse', icon: Star },
  { key: 'notes', label: 'Observações', icon: MessageSquare },
]
const filteredProcedures = computed(() => procedures.value.filter((item) => item.name.toLowerCase().includes(search.value.toLowerCase())))
const preview = computed(() => !program.value ? { fields: [], branding: {} } : { branding: { ...program.value.content }, fields: [
  { key: 'full_name', type: 'text', label: 'Nome completo', enabled: true, required: true, order: 0 },
  { key: 'phone', type: 'phone', label: 'WhatsApp', enabled: true, required: true, order: 1 },
  { key: 'email', type: 'email', label: 'E-mail', ...program.value.fields.email, order: 2 },
  { key: 'objective', type: 'select', label: 'Qual seu principal objetivo?', ...program.value.fields.objective, options: program.value.fields.objective.options, order: 3 },
  { key: 'service_interest', type: 'select', label: 'Qual serviço você tem interesse?', ...program.value.fields.serviceInterest, options: procedures.value.filter((item) => program.value.fields.serviceInterest.serviceIds.map(String).includes(String(item.id))).map((item) => ({ value: item.id, label: item.name })), order: 4 },
  { key: 'notes', type: 'textarea', label: 'Observações', ...program.value.fields.notes, order: 5 },
] })
const previewPage = computed(() => ({ form: { ...preview.value, branding: { ...preview.value.branding, clinicName: authStore.user?.clinic?.marketingName || authStore.user?.clinic?.name || 'Sua clínica', coverImage: program.value?.content?.coverImageUrl || '' }, consent: { privacy: { enabled: true, required: true, text: 'Declaro que li e concordo com a Política de Privacidade e autorizo o tratamento dos dados informados.' }, whatsappContact: { enabled: true, required: false, text: 'Aceito ser contatado(a) pela clínica por WhatsApp.' } }, success: { title: 'Tudo certo!', message: 'Recebemos seus dados com sucesso.' }, referrerName: 'Ana' } }))

async function loadLeads() { leadsLoading.value = true; try { const { data } = await getReferralLeads({ search: leadSearch.value || undefined, status: leadStatus.value || undefined }); leads.value = data.leads; referralMetrics.value = data.metrics } finally { leadsLoading.value = false } }
async function changeStatus(lead, event) { const previous = lead.status; lead.status = event.target.value; try { await updateReferralLeadStatus(lead._id, lead.status); await loadLeads() } catch { lead.status = previous } }
async function openLead(id) { const { data } = await getReferralLead(id); selectedLead.value = data.lead }
onMounted(async () => { try { const [a, b] = await Promise.all([getReferralProgram(), getReferralProcedures(), loadLeads()]); program.value = a.data.program; procedures.value = b.data.procedures } finally { loading.value = false } })
async function save() { saving.value = true; message.value = ''; try { const { data } = await updateReferralProgram({ enabled: program.value.enabled, content: { ...program.value.content, coverImage: program.value.content.coverImage?._id || program.value.content.coverImage || null }, fields: program.value.fields }); program.value = data.program; message.value = 'Configuração salva.' } catch (error) { message.value = error.response?.data?.error?.message || error.response?.data?.message || 'Não foi possível salvar.' } finally { saving.value = false } }
async function upload(event) { const file = event.target.files?.[0]; if (!file) return; const body = new FormData(); body.append('image', file); body.append('category', 'branding'); const { data } = await uploadImage(body); program.value.content.coverImage = data.uploadId; program.value.content.coverImageUrl = data.signedUrl }
function addObjective() { program.value.fields.objective.options.push({ value: `objective_${Date.now()}`, label: 'Novo objetivo' }) }
function removeObjective(index) { if (program.value.fields.objective.options.length > 1) program.value.fields.objective.options.splice(index, 1) }
</script>

<template>
  <main class="referrals-page">
    <header class="page-heading"><div><h1>Página de indicação</h1><p>Configure como será a página que seus pacientes compartilharão com amigos e conhecidos.</p></div><div class="section-switcher"><button :class="{ active: section === 'referrals' }" @click="section = 'referrals'; view = 'edit'">Indicações</button><button :class="{ active: section === 'config' }" @click="section = 'config'; view = 'edit'">Configuração</button></div></header>
    <section v-if="section === 'referrals'" class="operations"><div class="summary-cards"><article><b>{{ referralMetrics.total || 0 }}</b><span>Total de indicações</span></article><article><b>{{ referralMetrics.new || 0 }}</b><span>Novas</span></article><article><b>{{ referralMetrics.scheduled || 0 }}</b><span>Agendadas</span></article><article><b>{{ referralMetrics.converted || 0 }}</b><span>Convertidas</span></article><article><b>{{ referralMetrics.conversionRate || 0 }}%</b><span>Taxa de conversão</span></article></div><div class="lead-toolbar"><label><Search :size="18" /><input v-model="leadSearch" placeholder="Buscar indicado ou indicador..." @keyup.enter="loadLeads" /></label><select v-model="leadStatus" @change="loadLeads"><option v-for="item in statuses" :key="item.value" :value="item.value">{{ item.label }}</option></select><button @click="loadLeads">Buscar</button></div><div class="leads-table"><div v-if="leadsLoading" class="loading"><LoaderCircle class="spin" :size="22" /> Carregando...</div><div v-else-if="!leads.length" class="empty-leads">Nenhuma indicação recebida ainda.</div><table v-else><thead><tr><th>Indicado</th><th>Indicador</th><th>WhatsApp</th><th>Objetivo</th><th>Serviço</th><th>Status</th><th>Data</th></tr></thead><tbody><tr v-for="lead in leads" :key="lead._id"><td>{{ lead.fullName }}</td><td>{{ lead.referrerName }}</td><td>{{ lead.phone }}</td><td>{{ lead.objective || '—' }}</td><td>{{ lead.serviceInterestLabel || '—' }}</td><td><select class="status-select" :value="lead.status" @change="changeStatus(lead, $event)"><option v-for="item in statuses.slice(1)" :key="item.value" :value="item.value">{{ item.label }}</option></select></td><td>{{ new Date(lead.createdAt).toLocaleDateString('pt-BR') }}</td></tr></tbody></table></div></section>

    <section v-else class="configuration-section">
      <div v-if="loading" class="loading"><LoaderCircle class="spin" :size="24" /> Carregando...</div>
      <template v-else-if="view === 'edit'">
        <section class="config-card content-card"><div class="card-title"><span>1</span><h2>Conteúdo</h2></div><div class="content-grid"><div class="content-fields"><label>Título da página <Info :size="16" /><input v-model="program.content.title" maxlength="160" /><small>{{ program.content.title.length }}/160</small></label><label>Texto de apresentação <Info :size="16" /><textarea v-model="program.content.description" maxlength="1000" /><small>{{ program.content.description.length }}/1000</small></label><label>Texto do botão <Info :size="16" /><input v-model="program.content.buttonText" maxlength="80" /><small>{{ program.content.buttonText.length }}/80</small></label></div><div class="cover-column"><label>Imagem de capa <em>(opcional)</em> <Info :size="16" /></label><label class="cover-upload"><img v-if="program.content.coverImageUrl" :src="program.content.coverImageUrl" alt="Capa" /><span v-else class="cover-art"></span><span class="cover-action">{{ program.content.coverImageUrl ? 'Alterar imagem' : 'Adicionar imagem' }}</span><input type="file" accept="image/png,image/jpeg,image/webp" @change="upload" /></label><small>Recomendado: 1200×400px • JPG, PNG ou WEBP</small></div></div></section>

        <section class="config-card fields-card"><div class="card-title"><span>2</span><h2>Campos</h2></div><p>Nome completo e WhatsApp são sempre ativos e obrigatórios.</p><div class="fields-layout"><div class="fields-table"><div class="field-head"><span>Campo</span><span>Ativo</span><span>Obrigatório</span></div><div v-for="field in fields" :key="field.key" class="field-row"><span class="field-name"><component :is="field.icon" :size="21" /> {{ field.label }}</span><label class="switch"><input v-model="program.fields[field.key].enabled" type="checkbox" /><span></span></label><label class="check"><input v-model="program.fields[field.key].required" :disabled="!program.fields[field.key].enabled" type="checkbox" /><span>✓</span></label></div></div><aside class="fields-info"><Info :size="24" /><p>Nome completo e WhatsApp são sempre coletados, ativos e obrigatórios na página de indicação.</p></aside></div></section>

        <section class="config-card objectives-card"><header><div><div class="card-title"><span>3</span><h2>Objetivo principal</h2></div><p>Gerencie as opções que os indicados poderão escolher.</p></div><button class="outline-button" @click="addObjective"><Plus :size="16" /> Adicionar opção</button></header><div class="objective-list"><div v-for="(option, index) in program.fields.objective.options" :key="option.value" class="objective-row"><GripVertical :size="18" /><input v-model="option.label" maxlength="120" /><button title="Editar"><Pencil :size="17" /></button><button title="Excluir" :disabled="program.fields.objective.options.length === 1" @click="removeObjective(index)"><Trash2 :size="17" /></button></div></div></section>

        <section class="config-card services-card"><header><div><div class="card-title"><span>4</span><h2>Serviço de interesse</h2></div><p>Selecione os serviços disponíveis para escolha.</p></div><label class="search"><Search :size="20" /><input v-model="search" placeholder="Buscar serviço..." /></label></header><div class="service-list"><label v-for="item in filteredProcedures" :key="item.id" class="service-item"><input v-model="program.fields.serviceInterest.serviceIds" type="checkbox" :value="item.id" /><span>✓</span>{{ item.name }}</label></div></section>

        <section class="config-card privacy-card"><div class="card-title"><span>5</span><h2>Privacidade e consentimento</h2></div><p>Textos padronizados da Agenda Doutor, que já incluem suas informações.</p><div class="privacy-row"><span><ShieldCheck :size="22" /> Política de Privacidade e tratamento de dados</span><button>Visualizar <ExternalLink :size="17" /></button></div><div class="privacy-row"><span><ShieldCheck :size="22" /> Autorização de contato por WhatsApp</span><button>Visualizar <ExternalLink :size="17" /></button></div></section>

        <footer class="editor-footer"><span>{{ message }}</span><div class="footer-actions"><button class="preview-button" @click="view = 'preview'"><Eye :size="17" /> Visualizar preview</button><button class="save-button" :disabled="saving" @click="save"><Save :size="17" /> {{ saving ? 'Salvando...' : 'Salvar alterações' }}</button></div></footer>
      </template>
      <section v-else class="preview-screen"><header class="preview-toolbar"><button class="preview-button" @click="view = 'edit'"><ArrowLeft :size="17" /> Voltar para configuração</button><h2>Preview da página de indicação</h2></header><PublicFormView :preview-config="previewPage" /></section>
    </section>
  </main>
</template>

